const rigOf = sp => (rigsOn && SPRITES[sp] && SPRITES[sp].rig && RIGS[sp]) ? rigPrep(RIGS[sp]) : null;
// a rig with a swim clip is drawn in the water (rigSvg's waterline) instead of falling back to a swim strip
const rigSwims = sp => { const R = rigOf(sp); return !!(R && R.clips.swim); };

// sparse frames ({part index: r or [r, dx, dy]}) become flat arrays of r, dx, dy for every part
function rigPrep(R){
  if(R.ready) return R;
  const n = R.parts.length;
  for(const c of Object.values(R.clips)) c.dense = c.frames.map(f => {
    const a = new Float32Array(n * 3);
    for(const k in f){ if(k === "v") continue; const v = f[k]; if(Array.isArray(v)){ a[k*3] = v[0]; a[k*3 + 1] = v[1]; a[k*3 + 2] = v[2]; } else a[k*3] = v; }
    return a;
  });
  // which parts each frame shows: a part's default (o:1 is hidden), then the frame's own v
  R.vis0 = Uint8Array.from(R.parts, p => p.o ? 0 : 1);
  R.swaps = R.parts.some(p => p.o) || Object.values(R.clips).some(c => c.frames.some(f => f.v));
  for(const c of Object.values(R.clips)) c.vis = c.frames.map(f => { const s = R.vis0.slice(); for(const k in f.v || {}) s[k] = f.v[k] ? 1 : 0; return s; });
  R.ready = true;
  return R;
}

// the pose a loop has at a point in its cycle (0 to 1, wrapping), tweened between its two key poses; returns which parts that key frame shows
function rigSample(R, clip, phase, out){
  const C = R.clips[clip], fr = C.dense, N = fr.length, t = (((phase % 1) + 1) % 1) * N, i = Math.floor(t) % N, u = t - Math.floor(t), A = fr[i], B = fr[(i + 1) % N];
  for(let k = 0; k < out.length; k++) out[k] = A[k] + (B[k] - A[k]) * u;
  return C.vis[i];
}

// each part's world matrix, [a, b, c, d, e, f] a part, from its parent's: parent * translate(x + dx, y + dy) * rotate(r)
function rigMatrices(R, pose, m){
  const parts = R.parts, done = new Uint8Array(parts.length);
  const go = i => {
    if(done[i]) return; done[i] = 1;
    const p = parts[i]; let a = 1, b = 0, c = 0, d = 1, e = 0, f = 0;
    if(p.p >= 0){ go(p.p); const o = p.p * 6; a = m[o]; b = m[o + 1]; c = m[o + 2]; d = m[o + 3]; e = m[o + 4]; f = m[o + 5]; }
    const r = pose[i*3] * Math.PI / 180, cs = Math.cos(r), sn = Math.sin(r), tx = p.x + pose[i*3 + 1], ty = p.y + pose[i*3 + 2], o = i * 6;
    m[o] = a*cs + c*sn; m[o + 1] = b*cs + d*sn; m[o + 2] = -a*sn + c*cs; m[o + 3] = -b*sn + d*cs; m[o + 4] = a*tx + c*ty + e; m[o + 5] = b*tx + d*ty + f;
  };
  for(let i = 0; i < parts.length; i++) go(i);
}
// a flipped part is mirrored about its joint, which its children don't share
// a part's visibility, for the attribute and for the live update
const rigShown = (R, g, i) => (g.vis || R.vis0)[i];
const rigTransform = (p, m, i) => { const o = i * 6, s = p.f ? -1 : 1; return `matrix(${(m[o]*s).toFixed(4)} ${(m[o + 1]*s).toFixed(4)} ${m[o + 2].toFixed(4)} ${m[o + 3].toFixed(4)} ${m[o + 4].toFixed(3)} ${m[o + 5].toFixed(3)})`; };

const rigState = R => ({cur:new Float32Array(R.parts.length * 3), from:new Float32Array(R.parts.length * 3), tgt:new Float32Array(R.parts.length * 3),
  mats:new Float64Array(R.parts.length * 6), vis:(R.clips.idle || R.clips.walk || {}).vis?.[0] || null, mode:null, blend:1, idleT:1, idleC:"idle", gap:RIG_IDLE.gap[0], restT:0, lock:false, last:performance.now(), wlk:0, swimT:0});

// the animal's picture, the same size and footing as a strip's: its cell fits two and a half dots across, the feet a little below the middle
// In water a rig with a swim clip is clipped at its waterline (C.wl, a cell row): the part above shows, the part below is a faint ghost, and a ripple line (the exhibit's water colors) sits on the line.
// The clip's height eases from "no waterline" to C.wl as it sinks in (g.wlk, 0 to 1), so it doesn't pop at the bank.
let rigClipN = 0;
const rigWl = (R, g) => { const top = R.h + 10, k = g.wlk * g.wlk * (3 - 2 * g.wlk); return top + (R.clips.swim.wl - top) * k; };
function rigWater(h){
  const e = state.exhibits.find(x => x.id === h.exhibitId), tx = e && WATER_TEX[biomeOf(e)];
  return tx ? {lit:tx.lit, dark:tx.dark} : {lit:"#9CCBE8", dark:"#2F6F9F"};
}
function rigSvg(sp, h){
  const R = rigOf(sp), S = SPRITES[sp], w = h.r * 2.5 * (S.size || 1), k = w / R.w, ht = R.h * k;
  const g = h.rg ??= rigState(R);
  rigMatrices(R, g.cur, g.mats);
  const tf = `translate(${(-w/2).toFixed(2)} ${(h.r*.5 - ht).toFixed(2)}) scale(${k.toFixed(5)})`, parts = () => R.parts.map((p, i) => `<image href="${spriteUrl(p.img)}" x="${p.ix}" y="${p.iy}" width="${p.iw}" height="${p.ih}" style="image-rendering:pixelated${rigShown(R, g, i) ? "" : ";display:none"}" transform="${rigTransform(p, g.mats, i)}"/>`).join("");
  if(!(h.swim && R.clips.swim)){ g.wlk = 0; return `<g class="spr" transform="scale(${h.face || 1} 1)"><g class="rig" transform="${tf}">${parts()}</g></g>`; }
  const id = h.cid ??= "rgc" + (++rigClipN), wl = rigWl(R, g), wc = rigWater(h), x0 = -R.w * .2, W = R.w * 1.4;
  return `<g class="spr" transform="scale(${h.face || 1} 1)"><defs><clipPath id="${id}a"><rect x="${x0}" y="-20" width="${W}" height="${(wl + 20).toFixed(2)}"/></clipPath><clipPath id="${id}b"><rect x="${x0}" y="${wl.toFixed(2)}" width="${W}" height="${R.h}"/></clipPath></defs>`
    + `<g class="rig-ghost" transform="${tf}" clip-path="url(#${id}b)" opacity=".3">${parts()}</g>`
    + `<g class="rig" transform="${tf}" clip-path="url(#${id}a)">${parts()}</g>`
    + `<g class="rig-wake" transform="${tf}" fill="none" shape-rendering="crispEdges" pointer-events="none"><path class="wk1" d="M${(R.w*.28).toFixed(1)} ${wl.toFixed(2)}H${(R.w*.98).toFixed(1)}" stroke="${wc.lit}" stroke-width="1" stroke-dasharray="6 3 2 4"/>`
    + `<path class="wk2" d="M${(R.w*.3).toFixed(1)} ${(wl + 1).toFixed(2)}H${(R.w*.96).toFixed(1)}" stroke="${wc.dark}" stroke-width="1" stroke-opacity=".7" stroke-dasharray="3 5 7 3"/></g></g>`;
}

// one frame of motion: walking by how far it has gone, standing still it holds a calm stance and plays the idle clip once now and then, and resting plays once and holds (while one of those plays, g.lock is set and map.js leaves the animal alone until it's done); a change of mode eases over RIG_BLEND seconds
function rigStep(h, mode){
  const R = rigOf(h.sp), g0 = h.el.querySelector(".rig"); if(!R || !g0) return;
  const g = h.rg ??= rigState(R), now = performance.now(), dt = Math.min(.1, (now - g.last) / 1000); g.last = now;
  const S = SPRITES[h.sp];
  g.lock = false;
  let vis = R.vis0;
  const swim = !!(h.swim && R.clips.swim);   // in the water everything it does is swimming: strokes by how far it goes, a slow float when it stops
  if(swim) mode = mode === "walk" ? "swim" : "float";
  if(swim){
    const C = R.clips.swim, N = C.dense.length;
    if(mode === "swim") vis = rigSample(R, "swim", (h.stride || 0) / (h.r * (S.rswim || S.rstep || S.step || .5) * N), g.tgt);
    else { g.swimT += dt * C.fps * .35 / N; vis = rigSample(R, "swim", g.swimT, g.tgt); }
  }
  else if(mode === "walk" && R.clips.walk) vis = rigSample(R, "walk", (h.stride || 0) / (h.r * (S.rstep || S.step || .5) * R.clips.walk.dense.length), g.tgt);
  else if(mode === "rest" && R.clips.rest){   // settle once, then hold the last frame until the act changes
    if(g.mode !== "rest") g.restT = 0;
    g.restT += dt * R.clips.rest.fps; const N = R.clips.rest.dense.length;
    vis = rigSample(R, "rest", Math.min(g.restT, N - 1) / N, g.tgt);
    g.lock = g.restT < N - 1;   // lying down finishes too
  }else if(R.clips.idle){
    // standing still it holds the idle clip's first frame and plays one of its idle clips (idle, idle2, ... picked at random) once: often as it stops, and again after a while of standing (never while eating, drinking or hiding)
    const can = !["eat", "drink", "hide"].includes(h.act), I = RIG_IDLE, ids = R.idles ??= Object.keys(R.clips).filter(k => /^idle\d*$/.test(k));
    const go = () => { g.idleC = ids[Math.floor(Math.random() * ids.length)]; g.idleT = 0; g.gap = I.gap[0] + Math.random() * (I.gap[1] - I.gap[0]); };
    if(!String(g.mode).startsWith("idle")){ g.idleT = 1; go(); if(!(can && Math.random() < I.chance)) g.idleT = 1; }
    else if(g.idleT >= 1 && can && (g.gap -= dt) <= 0) go();
    const C = R.clips[g.idleC];
    if(g.idleT < 1) g.idleT += dt * C.fps / C.dense.length;
    g.lock = g.idleT < 1;   // once it starts it finishes, whatever the animal's act says
    if(g.idleT < 1) vis = rigSample(R, g.idleC, g.idleT, g.tgt); else { g.tgt.set(R.clips.idle.dense[0]); vis = R.clips.idle.vis[0]; }
    mode = g.idleT < 1 ? "idle-" + g.idleC : "idle";   // a new mode eases in, so a clip that starts away from the standing pose doesn't jump
  }
  else g.tgt.fill(0);
  if(mode !== g.mode){ g.from.set(g.cur); g.blend = 0; g.mode = mode; }
  if(g.blend < 1){
    g.blend = Math.min(1, g.blend + dt / RIG_BLEND); const k = g.blend * g.blend * (3 - 2 * g.blend);
    for(let i = 0; i < g.cur.length; i++) g.cur[i] = g.from[i] + (g.tgt[i] - g.from[i]) * k;
  }else g.cur.set(g.tgt);
  rigMatrices(R, g.cur, g.mats);
  const kids = g0.children, flip = R.swaps && vis !== g.vis; g.vis = vis;
  for(let i = 0; i < R.parts.length; i++){ kids[i].setAttribute("transform", rigTransform(R.parts[i], g.mats, i)); if(flip) kids[i].style.display = vis[i] ? "" : "none"; }
  const gh = swim && h.el.querySelector(".rig-ghost");
  if(gh){   // the ghost under the waterline follows the parts; the waterline rises as it sinks in; the ripples drift
    const gk = gh.children; for(let i = 0; i < R.parts.length; i++){ gk[i].setAttribute("transform", rigTransform(R.parts[i], g.mats, i)); if(flip) gk[i].style.display = vis[i] ? "" : "none"; }
    g.wlk = Math.min(1, g.wlk + dt / RIG_BLEND); const wl = rigWl(R, g), id = h.cid;
    const ca = h.el.querySelector(`#${id}a rect`), cb = h.el.querySelector(`#${id}b rect`), w1 = h.el.querySelector(".wk1"), w2 = h.el.querySelector(".wk2");
    if(ca) ca.setAttribute("height", (wl + 20).toFixed(2)); if(cb) cb.setAttribute("y", wl.toFixed(2));
    if(w1){ w1.setAttribute("d", w1.getAttribute("d").replace(/^(M[\d.]+ )[\d.-]+/, `$1${wl.toFixed(2)}`)); w1.setAttribute("stroke-dashoffset", (now / 90 % 15).toFixed(1)); }
    if(w2){ w2.setAttribute("d", w2.getAttribute("d").replace(/^(M[\d.]+ )[\d.-]+/, `$1${(wl + 1).toFixed(2)}`)); w2.setAttribute("stroke-dashoffset", (-now / 130 % 18).toFixed(1)); }
  }
}

// draw every animal again from rigs (true) or strips (false)
function setRigs(on){
  rigsOn = !!on;
  try{ localStorage.setItem("genesis-rigs", rigsOn ? "1" : "0"); }catch{}
  for(const h of herd.values()){ h.rg = null; h.pose = null; }
  syncAnimals();
}
